package org.transittr;
import java.io.IOException;import java.util.*;import java.util.regex.*;import org.json.*;
/** EGO Cepte's station passage timetable; it is planned data, not live train positions. */
public final class EgoRailClient {
 private static final String BASE="https://egocptsrvand.ego.gov.tr/hibrit/action.asp?FNC=DuraklardanGecisSaatleri&HAT=";
 private static final String[][] CODES={{"B1","B11","B10","B8","B7","B6","B5","B3","B2","B1","B12","B13","B14","B15","B16","B18","B19","B20","B21","B22","B23","B24","B25","B26","B27"},{"M123","M33","M32","M29","M30","M28","M31","M26","M24","M27","M34","M25","M1","M2","M3","M4","M5","M6","M7","M8","M9","M10","M11","M12","M21","M19","M22","M18","M13","M14","M23","M17","M15","M16","M20"},{"M1","M1","M2","M3","M4","M5","M6","M7","M8","M9","M10","M11","M12"},{"M2","M1","M25","M34","M27","M24","M26","M31","M28","M30","M29","M32","M33"},{"M3","M12","M21","M19","M22","M18","M13","M14","M23","M17","M15","M16","M20"},{"M4","M412","M411","M410","M49","M48","M47","M46","M45","M44","M43","M42","M41"},{"A1","A14","A12","A10","A8","A6","A4","A2","M1","A3","A5","A7"}};
 public static final class LineResult {public String text;public int successfulDirections;}
 private static final HashMap<String,String> cache=new HashMap<String,String>();private static final HashMap<String,Long> cachedAt=new HashMap<String,Long>();
 private static synchronized String fetch(String code)throws IOException{long now=System.currentTimeMillis();Long at=cachedAt.get(code);if(at!=null&&now-at.longValue()<60000&&now>=at.longValue())return cache.get(code);String json=ApiHttp.get(BASE+code);try{JSONObject root=new JSONObject(json);if(!"TRUE".equalsIgnoreCase(root.optString("status"))||root.optJSONArray("table")==null)throw new IOException("EGO tarife yanıtı geçersiz");}catch(JSONException e){throw new IOException("EGO tarife yanıtı okunamadı");}cache.put(code,json);cachedAt.put(code,Long.valueOf(now));return json;}
 static String stationCode(JourneyData.RailLine line,String station,boolean reverse){int position=-1;for(int i=0;i<line.stations.size();i++)if(station.equals(line.stations.get(i).name)){position=i;break;}if(position<0)return "";for(String[] row:CODES)if(line.id.equals(row[0])&&position+1<row.length){if(line.id.equals("M4")&&reverse)return "M4"+(13+position);return row[position+1];}return "";}
 private static boolean dayMatches(String label,long start){String s=label.toUpperCase(new Locale("tr","TR"));Calendar c=Calendar.getInstance(TimeZone.getTimeZone("GMT+03:00"));c.setTimeInMillis(start);int d=c.get(Calendar.DAY_OF_WEEK);if(d==Calendar.SATURDAY)return s.indexOf("CUMARTES")>=0;if(d==Calendar.SUNDAY)return s.indexOf("PAZAR")>=0;return s.indexOf("HAFTA")>=0;}
 /** Returns only official station times in the current service day. */
 public static ArrayList<Long> parseTimes(String json,String stationCode,long now)throws IOException{try{
  JSONObject root=new JSONObject(json);if(!"TRUE".equalsIgnoreCase(root.optString("status")))throw new IOException("EGO tarife yanıtı başarısız");JSONArray rows=root.optJSONArray("table");if(rows==null||rows.length()>300)throw new IOException("EGO tarife biçimi değişmiş");JSONObject station=null;for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);if(stationCode.equalsIgnoreCase(row.optString("kod",""))){station=row;break;}}
  if(station==null)throw new IOException("EGO istasyonu bulunamadı");long start=RailEstimator.serviceStart(now);if(!dayMatches(station.optString("tur",""),start))throw new IOException("EGO tarife günü eşleşmiyor");String times=station.optString("saat","");if(times.length()>30000)throw new IOException("EGO saat listesi çok uzun");Matcher m=Pattern.compile("(?<![0-9])([01]?[0-9]|2[0-3]):([0-5][0-9])(?![0-9])").matcher(times);TreeSet<Long> sorted=new TreeSet<Long>();int count=0;while(m.find()){if(++count>1200)throw new IOException("EGO saat sınırı");int h=Integer.parseInt(m.group(1)),minute=Integer.parseInt(m.group(2));long sec=h*3600L+minute*60L;if(h<6)sec+=86400;long at=start+sec*1000;if(at+60000>now)sorted.add(Long.valueOf(at));}return new ArrayList<Long>(sorted);
 }catch(JSONException e){throw new IOException("EGO saat listesi okunamadı");}}
 public static LineResult query(JourneyData.RailLine line,String station,long now){LineResult out=new LineResult();String[] codes,destinations;if(line==null||line.city!=0){out.text="Ankara metro hattı seç.";return out;}
  if(line.id.equals("M1")||line.id.equals("M2")||line.id.equals("M3")||line.id.equals("M123")){codes=new String[]{"M1-D","M1-G"};destinations=new String[]{"OSB-Törekent","Koru"};}else if(line.id.equals("M4")){codes=new String[]{"M4-D","M4-G"};destinations=new String[]{"15 Temmuz Kızılay","Şehitler"};}else if(line.id.equals("A1")){codes=new String[]{"A1-D","A1-G"};destinations=new String[]{"Dikimevi","AŞTİ"};}else if(line.id.equals("B1")){codes=new String[]{"B1-D","B1-G"};destinations=new String[]{"Sincan","Kayaş"};}else{out.text="Bu hatta EGO istasyon saatleri yok.";return out;}
  StringBuilder b=new StringBuilder("EGO Cepte istasyon tarifesi · planlı geçişler\nCanlı tren konumu değildir; gecikme ve iptaller değişebilir.\n\n");
  for(int i=0;i<2;i++){b.append(destinations[i]).append(" yönü\n");String id=stationCode(line,station,i==1);try{if(id.length()==0)throw new IOException("İstasyon eşleştirilemedi");ArrayList<Long> values=parseTimes(fetch(codes[i]),id,now);out.successfulDirections++;if(values.isEmpty())b.append("Bugün için başka geçiş bulunamadı.\n");else{int shown=0;for(Long at:values){long delta=at.longValue()-now;long minutes=delta<=0?0:(delta+59999)/60000;b.append(minutes==0?"Şimdi":minutes+" dk");Calendar clock=Calendar.getInstance(TimeZone.getTimeZone("GMT+03:00"));clock.setTimeInMillis(at.longValue());b.append(String.format(Locale.US," · %02d:%02d\n",clock.get(Calendar.HOUR_OF_DAY),clock.get(Calendar.MINUTE)));if(++shown>=3)break;}}}catch(IOException e){b.append("Saat alınamadı: ").append(e.getMessage()).append("\n");}b.append("\n");}
  b.append("Kaynak: EGO Cepte · Duraklardan geçiş saatleri");out.text=b.toString();return out;
 }
}
